\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\title{Field Report: Traverses Across the Kettle Moraine Outwash Plain}
\author{D. Whitfield}
\date{April 2026}
\begin{document}
\maketitle

\section{Overview}
Between 14 and 18 April we walked three north--south traverses across
the outwash plain, logging exposures, gravel bars and kettle lakes.
Weather was dry throughout, and access was unrestricted.

\section{Observations}
\subsecton{Gravel Bars}
The bars east of the esker ridge are armoured with cobble lags over
coarse sand. Imbrication indicates palaeoflow toward the south-west.

\subsection{Kettle Lakes}
Six kettle lakes were visited; all are groundwater-fed, with marl
benches exposed along the northern shores.

\section{Samples}
Twelve sediment samples were bagged for grain-size analysis and will be
submitted to the laboratory next week.
\end{document}

